const resolveTaskParticipant = `-- name: ResolveTaskParticipant :one
SELECT actor.id,actor.tenant_id,actor.kind,actor.display_name,
       registration.agent_management_id,registration.status AS registration_status
FROM actors actor
JOIN agent_registrations registration
  ON registration.actor_id=actor.id AND registration.tenant_id=actor.tenant_id
WHERE actor.id=$1::text
  AND actor.tenant_id=$2::text
FOR KEY SHARE OF actor,registration
`

type ResolveTaskParticipantParams struct {
	ActorID  string `json:"actor_id"`
	TenantID string `json:"tenant_id"`
}

type ResolveTaskParticipantRow struct {
	ID                 string      `json:"id"`
	TenantID           string      `json:"tenant_id"`
	Kind               string      `json:"kind"`
	DisplayName        string      `json:"display_name"`
	AgentManagementID  pgtype.Text `json:"agent_management_id"`
	RegistrationStatus string      `json:"registration_status"`
}

func (q *Queries) ResolveTaskParticipant(ctx context.Context, arg ResolveTaskParticipantParams) (ResolveTaskParticipantRow, error) {
	row := q.db.QueryRow(ctx, resolveTaskParticipant, arg.ActorID, arg.TenantID)
	var i ResolveTaskParticipantRow
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.Kind,
		&i.DisplayName,
		&i.AgentManagementID,
		&i.RegistrationStatus,
	)
	return i, err
}

